mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.ENDPOINT_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.ASSET_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.ADDRESS,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.ENDPOINT_ID = #{endpointId}
AND T1.ASSET_ID = #{assetId}
AND T1.ADDRESS = #{address}
AND T1.ENDPOINT_TYPE_CD = #{endpointTypeCd}
AND T1.PRIMARY_YN = #{primaryYn}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.ENDPOINT_ID AS ENDPOINT_ID, T1.ASSET_ID AS ASSET_ID, T1.ENDPOINT_TYPE_CD AS ENDPOINT_TYPE_CD, T1.ADDRESS AS ADDRESS, T1.PORT_NO AS PORT_NO, T1.PROTOCOL_CD AS PROTOCOL_CD, T1.PRIMARY_YN AS PRIMARY_YN, T1.REMARK AS REMARK, T1.REG_USER_ID AS REG_USER_ID, T1.REG_DTM AS REG_DTM, T1.CHG_USER_ID AS CHG_USER_ID, T1.CHG_DTM AS CHG_DTM
      FROM TB_IF_NETWORK_EP_PILOT T1

     ORDER BY T1.REG_DTM DESC, T1.ENDPOINT_ID ASC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

SELECT COUNT(*) FROM TB_IF_NETWORK_EP_PILOT T1
 WHERE T1.ADDRESS = #{address}
   AND COALESCE(T1.PORT_NO, '') = #{portNo}
   AND T1.ENDPOINT_ID <> #{endpointId}
